# For each cell, maintain a set of possible values
# Initialize with all values 0..10 for empty cells, or the fixed value for filled cells

def init_domains(grid):
    domains = [[set(range(n)) if grid[i][j] == -1 else {grid[i][j]} for j in range(n)] for i in range(n)]
    return domains

def propagate(domains):
    # Simple AC-3 style propagation
    changed = True
    while changed:
        changed = False
        # For each row
        for i in range(n):
            for v in range(n):
                # Find cells in row i that can take value v
                cells_with_v = [j for j in range(n) if v in domains[i][j]]
                if len(cells_with_v) == 0:
                    return False  # Domain wipeout
                if len(cells_with_v) == 1:
                    j = cells_with_v[0]
                    if len(domains[i][j]) > 1:
                        domains[i][j] = {v}
                        changed = True
        # For each column
        for j in range(n):
            for v in range(n):
                cells_with_v = [i for i in range(n) if v in domains[i][j]]
                if len(cells_with_v) == 0:
                    return False
                if len(cells_with_v) == 1:
                    i = cells_with_v[0]
                    if len(domains[i][j]) > 1:
                        domains[i][j] = {v}
                        changed = True
        # For each cell, remove values that are already used in its row/column
        for i in range(n):
            for j in range(n):
                if len(domains[i][j]) == 1:
                    v = next(iter(domains[i][j]))
                    # Remove v from other cells in same row
                    for j2 in range(n):
                        if j2 != j and v in domains[i][j2]:
                            domains[i][j2].remove(v)
                            changed = True
                            if len(domains[i][j2]) == 0:
                                return False
                    # Remove v from other cells in same column
                    for i2 in range(n):
                        if i2 != i and v in domains[i2][j]:
                            domains[i2][j].remove(v)
                            changed = True
                            if len(domains[i2][j]) == 0:
                                return False
    return True

def select_unassigned(domains):
    # MRV heuristic: choose cell with smallest domain > 1
    best = None
    best_size = n + 1
    for i in range(n):
        for j in range(n):
            sz = len(domains[i][j])
            if sz > 1 and sz < best_size:
                best_size = sz
                best = (i, j)
    return best

def solve(domains):
    if not propagate(domains):
        return None

    cell = select_unassigned(domains)
    if cell is None:
        # All cells assigned
        result = [[next(iter(domains[i][j])) for j in range(n)] for i in range(n)]
        return result

    i, j = cell
    for v in sorted(domains[i][j]):
        # Try value v
        new_domains = [row[:] for row in domains]
        new_domains[i][j] = {v}
        result = solve(new_domains)
        if result is not None:
            return result
    return None

